federalIndexes.query:
PREFIX jolux: <http://data.legilux.public.lu/resource/ontology/jolux#>
SELECT DISTINCT ?work ?version ?start ?end ?expression ?xml WHERE {
VALUES ?work { <https://fedlex.data.admin.ch/eli/cc/2002/510> <https://fedlex.data.admin.ch/eli/cc/1993/3043_3043_3043> <https://fedlex.data.admin.ch/eli/cc/1993/3080_3080_3080> <https://fedlex.data.admin.ch/eli/cc/2021/373> <https://fedlex.data.admin.ch/eli/cc/2021/376> }

      ?version jolux:isMemberOf ?work; jolux:dateApplicability ?start.
      OPTIONAL { ?version jolux:dateEndApplicability ?end }
      OPTIONAL {
        ?version jolux:isRealizedBy ?expression.
        ?expression jolux:language <http://publications.europa.eu/resource/authority/language/DEU>;
          jolux:isEmbodiedBy ?manifestation.
        ?manifestation jolux:format <http://publications.europa.eu/resource/authority/file-type/XML>;
          jolux:isExemplifiedBy ?xml.
      }
      FILTER(str(?start) <= "2027-12-31" && (!BOUND(?end) || str(?end) >= "2026-01-01"))
    } ORDER BY ?work ?start

PREFIX jolux: <http://data.legilux.public.lu/resource/ontology/jolux#>
SELECT DISTINCT ?work ?impact ?date ?target ?source WHERE {
VALUES ?work { <https://fedlex.data.admin.ch/eli/cc/2002/510> <https://fedlex.data.admin.ch/eli/cc/1993/3043_3043_3043> <https://fedlex.data.admin.ch/eli/cc/1993/3080_3080_3080> <https://fedlex.data.admin.ch/eli/cc/2021/373> <https://fedlex.data.admin.ch/eli/cc/2021/376> }

      ?impact jolux:impactToLegalResource ?target;
        jolux:legalResourceImpactHasDateEntryInForce ?date.
      { ?target jolux:legalResourceSubdivisionIsPartOf ?work. } UNION { FILTER(?target = ?work) }
      OPTIONAL { ?impact jolux:impactFromLegalResource/jolux:legalResourceSubdivisionIsPartOf ?source }
      FILTER(str(?date) >= "2026-01-01" && str(?date) <= "2027-12-31")
    } ORDER BY ?work ?date ?target

versionIndex.query:
PREFIX jolux: <http://data.legilux.public.lu/resource/ontology/jolux#>
SELECT DISTINCT ?version ?start ?end ?xml WHERE {
?version jolux:isMemberOf <https://fedlex.data.admin.ch/eli/cc/2007/804>; jolux:dateApplicability ?start.
OPTIONAL { ?version jolux:dateEndApplicability ?end }
OPTIONAL { ?version jolux:isRealizedBy ?exp. ?exp jolux:language <http://publications.europa.eu/resource/authority/language/DEU>; jolux:isEmbodiedBy ?m. ?m jolux:format <http://publications.europa.eu/resource/authority/file-type/XML>; jolux:isExemplifiedBy ?xml. }
FILTER(str(?start) <= "2027-12-31" && (!BOUND(?end) || str(?end) >= "2026-01-01"))
} ORDER BY ?start

futureIndex.query:
PREFIX jolux: <http://data.legilux.public.lu/resource/ontology/jolux#>
SELECT DISTINCT ?impact ?date ?target ?source WHERE {
?impact jolux:impactToLegalResource ?target; jolux:legalResourceImpactHasDateEntryInForce ?date.
?target jolux:legalResourceSubdivisionIsPartOf <https://fedlex.data.admin.ch/eli/cc/2007/804>.
OPTIONAL {?impact jolux:impactFromLegalResource/jolux:legalResourceSubdivisionIsPartOf ?source}
FILTER(str(?date) >= "2026-09-30" && str(?date) <= "2027-12-31")
} ORDER BY ?date ?target
